*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:#e8e4da;color:var(--ink);font-family:var(--sans);overflow:hidden}.game-shell{height:100dvh;min-height:600px;max-width:1600px;margin:auto;padding:20px 34px 14px;display:flex;flex-direction:column;gap:14px}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;flex:none}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:#34473f;font:500 11px var(--mono);letter-spacing:.13em}.brand b{color:#97a097;font-weight:400}.brand-icon{font-size:20px;color:#bf9255}.location{display:flex;align-items:center;gap:9px;color:#69756d;font:11px var(--mono);letter-spacing:.04em}.loc-dot{width:7px;height:7px;background:#d39d58;border-radius:50%;box-shadow:0 0 0 4px #d39d5825}.top-actions{display:flex;gap:9px;align-items:center}.day-pill{font:10px var(--mono);letter-spacing:.08em;color:#68756b;background:#e1e3d8;padding:9px 13px;border-radius:20px}.icon-button{width:34px;height:34px;border:1px solid #d5d8ce;background:#f3f2eb;border-radius:50%;color:#526558;font-size:18px;cursor:pointer}.icon-button:hover{background:#fff}
