58%);color:#fff}.eyebrow{font:9px var(--mono);letter-spacing:.16em;color:#b29c71}.start-card h1{font:600 clamp(38px,5vw,63px)/.98 var(--serif);letter-spacing:-.04em;margin:19px 0 17px}.start-card h1 i{color:#e2b675;font-weight:600}.start-card p{max-width:345px;color:#d3d8cf;font-size:13px;line-height:1.75;margin:0 0 26px}.primary-button{display:flex;align-items:center;gap:26px;padding:13px 17px;border:0;border-radius:4px;background:#e4b979;color:#24342d;font:600 12px var(--sans);cursor:pointer;box-shadow:0 4px 16px #0e1c1744;transition:.2s}.primary-button:hover{background:#f1ce97;transform:translateY(-2px)}.primary-button span{font-size:18px}.start-foot{display:flex;gap:20px;margin-top:34px;color:#b5c1b4;font:8px var(--mono);letter-spacing:.08em}.start-cat{position:absolute;right:18%;bottom:17%;font-size:clamp(54px,9vw,100px);filter:drop-shadow(0 10px 10px #16221777);transform:scaleX(-1);opacity:.93}.pause-badge{display:none;position:absolute;inset:0;z-index:3;align-items:center;justify-content:center;gap:10px;background:#1f302f85;color:white;font:11px var(--mono);letter-spacing:.2em}.pause-badge.show{display:flex}.pause-badge span{font-size:16px}.mobile-controls,.mobile-action{display:none}
.sidebar{min-height:0;display:flex;flex-direction:column;gap:12px}.cat-card,.journal-card,.inventory-card{background:var(--panel);border:1px solid #e8e3d8;border-radius:9px;padding:17px 18px}.cat-card{flex:none}.cat-card-head{display:flex;justify-content:space-between;align-items:center}.cat-card h2{margin:5px 0 0;font:600 25px var(--serif);letter-spacing:-.02em}.avatar{width:43px;height:43px;border-radius:50%;background:#f1eadb;display:grid;place-items:center;font-size:25px}.cat-mood{margin:8px 0 15px;color:#7a8279;font:italic 12px var(--serif)}.needs{display:flex;flex-direction:column;gap:9px}.need-row{display:grid;grid-template-columns:17px 53px 1fr 22px;gap:7px;align-items:center}.need-icon{font-size:13px;text-align:center}.hunger{color:#d39c5e}.thirst{color:#6ca9ad}.energy{color:#88a06e}.need-name{font:8px var(--mono);letter-spacing:.07em;color:#8a928a}.need-row>b{font:9px var(--mono);font-weight:400;text-align:right;color:#7c887f}.meter{height:5px;background:#eae9e1;border-radius:6px;overflow:hidden}.fill{height:100%;display:block;border-radius:6px;transition:width .3s}.hunger-fill{background:#d39c5e}.thirst-fill{background:#76b8bb}.energy-fill{background:#91a773}.journal-card,.inventory-card{flex:1;min-height:0}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.section-heading h3{margin:4px 0 0;font:600 17px var(--serif)}.journal-count,.inventory-total{font:10px var(--mono);color:#869084}.journal-list,.inventory-list{display:flex;flex-direction:column;gap:0}.journal-item{display:flex;align-items:flex-start;gap:9px;padding:9px 0;border-top:1px solid #f0ede4;color:#56645b;font-size:11px;line-height:1.4}.journal-item:first-child{border-top:0}.journal-check{flex:none;width:15px;height:15px;border:1px solid #ccd0c4;border-radius:50%;display:grid;place-items:center;font-size:9px;color:#fff;margin-top:1px}.journal-item.done .journal-check{background:#83946e;border-color:#83946e}.journal-item.done .journal-text{color:#a1a79d;text-decoration:line-through}.inventory-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.item-chip{display:flex;align-items:center;gap:7px;padding:7px 8px;border-radius:5px;background:#f5f3eb;color:#58665c;font-size:10px}.item-chip span{font-size:15px}.item-chip b{margin-left:auto;font:10px var(--mono);color:#8e978b}.empty-inventory{grid-column:1/-1;color:#a0a69c;font:italic 11px var(--serif);padding:8px 0}.sidebar-note{display:flex;align-items:center;gap:11px;padding:0 6px;color:#718075}.sidebar-note>span{font-size:19px;color:#c39b60}.sidebar-note p{font-size:10px;line-height:1.6;margin:0}.sidebar-note b{font-weight:600;color:#526357}.bottom-bar{height:27px;flex:none;display:flex;align-items:center;justify-content:space-between;color:#737e74}.controls-hint{display:flex;align-items:center;gap:5px;font:9px var(--mono)}.key{min-width:17px;height:18px;padding:2px 4px;text-align:center;border:1px solid #d1d1c7;border-radius:3px;background:#f3f1e9;color:#67736a}.key-wide{padding-inline:7px}.controls-hint>span:not(.key){margin:0 7px 0 2px}.controls-hint i{height:13px;width:1px;background:#d2d1c7;margin:0 8px}.world-coords{font:9px var(--mono);letter-spacing:.1em;color:#91988e}
@media(max-width:1050px){.game-shell{padding:14px 18px 10px}.game-layout{grid-template-columns:minmax(0,1fr) 260px;gap:12px}.cat-card,.journal-card,.inventory-card{padding:14px}.sidebar{gap:9px}.start-cat{right:12%}}
@media(max-width:760px){body{overflow:auto}.game-shell{height:auto;min-height:100dvh;padding:9px 10px max(8px,env(safe-area-inset-bottom));gap:8px}.topbar{height:38px}.brand{font-size:9px;gap:6px}.brand-icon{font-size:17px}.location{font-size:9px}.top-actions{gap:5px}.day-pill{font-size:8px;padding:7px 8px}.icon-button{width:29px;height:29px;font-size:15px}.game-layout{display:flex;flex-direction:column;gap:9px;flex:1}.world-frame{height:min(62dvh,590px);min-height:390px;flex:none;border-radius:9px}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cat-card{grid-column:1/-1;padding:12px 14px}.cat-card-head{float:left;gap:12px}.cat-card h2{font-size:21px}.avatar{width:36px;height:36px;font-size:21px}.cat-mood{position:absolute;margin:6px 0 0 130px}.needs{display:grid;grid-template-columns:1fr;gap:6px;max-width:350px;margin-left:auto}.need-row{grid-template-columns:15px 48px minmax(50px,1fr) 20px;gap:5px}.need-name{font-size:7px}.journal-card,.inventory-card{padding:11px;min-height:158px}.section-heading{margin-bottom:7px}.section-heading h3{font-size:15px}.eyebrow{font-size:8px}.journal-item{font-size:10px;padding:7px 0}.item-chip{padding:6px;font-size:9px}.sidebar-note{display:none}.bottom-bar{height:21px}.controls-hint{font-size:8px;gap:3px}.key{min-width:15px;height:16px;padding:1px 3px}.controls-hint>span:not(.key){margin:0 3px}.controls-hint i{margin:0 4px;height:11px}.world-coords{font-size:7px}.scene-label{top:13px;left:13px}.scene-label b{font-size:8px}.scene-label small{font-size:10px}.weather-chip{top:13px;right:13px;font-size:8px}.start-overlay{padding:8%;background:linear-gradient(90deg,#17291ff0,#1d3028d9 60%,#1e2e2260)}.start-card{width:78%}.start-card h1{font-size:clamp(40px,11vw,59px)}.start-card p{font-size:12px;max-width:280px}.start-foot{font-size:7px;gap:10px}.start-cat{right:8%;bottom:12%;font-size:60px;opacity:.6}.toast{bottom:76px;font-size:11px}.mobile-controls{display:grid;position:absolute;left:13px;bottom:15px;width:116px;height:104px;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:4px;z-index:2;opacity:.72}.pad{border:1px solid #ffffff73;background:#263a31aa;color:#fff;border-radius:8px;font-size:12px;touch-action:none}.pad.up{grid-area:1/2}.pad.left{grid-area:2/1}.pad.down{grid-area:2/2}.pad.right{grid-area:2/3}.mobile-action{display:block;position:absolute;right:18px;bottom:28px;width:52px;height:52px;border-radius:50%;border:1px solid #ffffff88;background:#d8aa6acc;color:white;font-size:22px;z-index:2;touch-action:none}.map-overlay{width:160px;top:45px;right:10px}.map-overlay>span{font-size:8px}}
@media(max-width:390px){.brand b{display:none}.location{max-width:128px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.day-pill{letter-spacing:0}.sidebar{grid-template-columns:1fr 1fr}.inventory-list{gap:5px}.item-chip{gap:4px}.controls-hint>span:not(.key){font-size:7px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('minimap');
  const mapCtx = mapCanvas.getContext('2d');
  const W = 100, H = 100, TILE = 44;
  const keys = new Set();
  const player = { x: 52.1, y: 54.2, dx: 1, dy: 0, hunger: 82, thirst: 76, energy: 94, moving: false, swim: false };
  const state = { started: false, paused: false, map: false, time: 0.23, day: 1, seconds: 0, last: 0, toastTimer: 0, waterFound: false, canalFound: false, foodFound: false, homeFound: false, sound: false, discovered: new Set(), inventory: { berries: 0, fish: 0, bugs: 0, feathers: 0 }, collected: new Set() };
  const locations = [
    { name: 'Juniper’s Porch', x: 52, y: 55, icon: '⌂', desc: 'A familiar little starting place' },
    { name: 'Canal de las Garzas', x: 49, y: 27, icon: '≈', desc: 'The water road, full of life' },
    { name: 'La Laguna', x: 25, y: 45, icon: '◉', desc: 'A cool, quiet place to drink' },
    { name: 'The Green Rows', x: 80, y: 52, icon: '✳', desc: 'Fields that reach the horizon' },
    { name: 'Coyote Hills', x: 13, y: 67, icon: '⌃', desc: 'Wind-carved paths and high views' },
    { name: 'The Saltgrass Marsh', x: 67, y: 13, icon: '♧', desc: 'Reeds whisper over shallow water' },
    { name: 'Sunset Flats', x: 44, y: 88, icon: '☼', desc: 'Warm stones, long shadows' },
    { name: 'Old Fig Tree', x: 61, y: 39, icon: '♣', desc: 'A generous patch of shade' }
  ];
  // The setting is an original, fictionalized landscape inspired by the Sonoran region—not a replica of a real home or street.
  const houses = [
    {x:46,y:49,w:4,h:3,color:'#d8b98a',roof:'#a75f48'}, {x:54,y:49,w:4,h:3,color:'#e6c997',roof:'#ad6a4e'},
    {x:41,y:55,w:4,h:3,color:'#cfae7b',roof:'#9c5946'}, {x:59,y:55,w:4,h:3,color:'#e2c99e',roof:'#ad7050'},
    {x:45,y:62,w:4,h:3,color:'#e2c599',roof:'#98604b'}, {x:55,y:63,w:4,h:3,color:'#d3b88a',roof:'#a9664a'},
    {x:36,y:44,w:4,h:3,color:'#d8c49c',roof:'#a7654a'}, {x:63,y:46,w:4,h:3,color:'#dac095',roof:'#a86148'},
    {x:70,y:42,w:4,h:3,color:'#d8bd8c',roof:'#9c6047'}, {x:73,y:62,w:4,h:3,color:'#ddc89e',roof:'#a5664b'}
  ];
  const resources = [];
  const fixedResources = [
    ['berries',39,57],['berries',57,35],['berries',34,48],['berries',63,72],['berries',74,32],['berries',18,54],['berries',86,65],['berries',48,82],
    ['fish',25,44],['fish',23,46],['fish',50,27],['fish',56,27],['fish',68,16],['fish',71,15],
    ['bugs',44,69],['bugs',79,70],['bugs',31,72],['bugs',89,48],['bugs',59,41],['bugs',14,76],
    ['feathers',41,30],['feathers',75,23],['feathers',21,61],['feathers',83,57]
  ];
  fixedResources.forEach((r,i)=>resources.push({type:r[0],x:r[1],y:r[2],id:`r${i}`}));
  const colors = { grass:'#9daa78', grass2:'#a8b681', town:'#c5b88c', field:'#a8aa71', desert:'#d2ad77', rock:'#969475', water:'#73aaa0', wet:'#88aa87', marsh:'#8da67d' };
  let viewW=800, viewH=600, dpr=1, toastTimeout;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function hash(x,y){let n=(x*374761393+y*668265263)|0;n=(n^(n>>>13))*1274126177;return ((n^(n>>>16))>>>0)/4294967295;}
  function terrain(x,y){
    if(x<0||y<0||x>=W||y>=H)return 'rock';
    const canalY=27+Math.sin(x*.16)*1.35+Math.sin(x*.043)*1.5;
    if(Math.abs(y-canalY)<2.05) return 'water';
    const lx=(x-25)/9, ly=(y-45)/5.5;
    if(lx*lx+ly*ly<1) return 'water';
    const px=71+Math.sin(y*.19)*2;
    if(Math.abs(x-px)<1.1 && y>32&&y<75) return 'water';
    if(y<20&&x>37&&x<81){return hash(x,y)>.36?'marsh':'wet';}
    if(x<20 && y>55){return hash(x,y)>.46?'rock':'desert';}
    if(y>76)return hash(x,y)>.16?'desert':'grass';
    if(x>67&&y>31&&y<76)return 'field';
    if(x>32&&x<68&&y>34&&y<74)return 'town';
    if(x<27&&y<77)return hash(x,y)>.75?'rock':'grass';
    return hash(x,y)>.62?'grass2':'grass';
  }
  function isHouse(x,y){return houses.some(h=>x>=h.x-.35&&x<=h.x+h.w+.2&&y>=h.y-.25&&y<=h.y+h.h+.2);}
  function blocked(x,y){if(x<.6||y<.6||x>W-.6||y>H-.6||isHouse(x,y))return true;const t=terrain(Math.floor(x),Math.floor(y));if(t==='rock'&&hash(Math.floor(x),Math.floor(y))>.74)return true;return false;}
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);viewW=Math.max(1,r.width);viewH=Math.max(1,r.height);canvas.width=Math.round(viewW*dpr);canvas.height=Math.round(viewH*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawMap();}
  function drawTile(tx,ty,sx,sy){
    const t=terrain(tx,ty), c=colors[t]||colors.grass, h=hash(tx,ty);
    ctx.fillStyle=c;ctx.fillRect(sx,sy,TILE+1,TILE+1);
    if(t==='water'){
      ctx.fillStyle='#c2dfc0';for(let i=0;i<2;i++){let px=sx+((h*53+i*27)%TILE),py=sy+((h*31+i*19)%TILE);ctx.fillRect(px,py,8+(i*3),1.5);}
      if(h>.73){ctx.fillStyle='#d2e8c2';ctx.fillRect(sx+7,sy+31,5,2);}
    } else if(t==='rock'){
      ctx.fillStyle='#777b65';ctx.globalAlpha=.22;ctx.fillRect(sx+8,sy+8,17,8);ctx.fillRect(sx+27,sy+26,10,6);ctx.globalAlpha=1;
    } else if(t==='field'){
      ctx.strokeStyle='#7e8959';ctx.globalAlpha=.28;ctx.lineWidth=1;
      for(let i=7;i<TILE;i+=10){ctx.beginPath();ctx.moveTo(sx+i,sy+2);ctx.lineTo(sx+i,sy+TILE);ctx.stroke();}ctx.globalAlpha=1;
    } else {
      ctx.fillStyle=t==='desert'?'#f0d093':'#617d58';ctx.globalAlpha=t==='desert'?.27:.22;
      for(let i=0;i<3;i++){const px=sx+hash(tx+i*7,ty+3)*TILE,py=sy+hash(tx+2,ty+i*13)*TILE;ctx.fillRect(px,py,2,2);}ctx.globalAlpha=1;
      if(t==='marsh'&&h>.48){ctx.strokeStyle='#66845f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(sx+15,sy+35);ctx.lineTo(sx+17,sy+23);ctx.lineTo(sx+20,sy+18);ctx.moveTo(sx+29,sy+38);ctx.lineTo(sx+28,sy+26);ctx.stroke();}
    }
  }
  function drawTree(x,y,s=1){
    const cx=x,cy=y;
    ctx.fillStyle='#344b39';ctx.beginPath();ctx.ellipse(cx,cy+8*s,10*s,4*s,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#745d3d';ctx.fillRect(cx-2*s,cy-2*s,4*s,10*s);
    ctx.fillStyle='#526e4a';ctx.beginPath();ctx.arc(cx,cy-5*s,9*s,0,Math.PI*2);ctx.arc(cx-6*s,cy-2*s,6*s,0,Math.PI*2);ctx.arc(cx+6*s,cy-1*s,6*s,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#78905b';ctx.beginPath();ctx.arc(cx-3*s,cy-8*s,4*s,0,Math.PI*2);ctx.fill();
  }
  function drawHouse(h,ox,oy){
    const x=ox+h.x*TILE,y=oy+h.y*TILE,w=h.w*TILE,hh=h.h*TILE;
    ctx.fillStyle='#4e4e3b55';ctx.fillRect(x+4,y+hh-2,w,9);
    ctx.fillStyle=h.color;ctx.fillRect(x,y+13,w,hh-13);
    ctx.fillStyle=h.roof;ctx.beginPath();ctx.moveTo(x-5,y+18);ctx.lineTo(x+w*.5,y-5);ctx.lineTo(x+w+5,y+18);ctx.closePath();ctx.fill();
    ctx.fillStyle='#e3d4ad';ctx.fillRect(x+w*.5-7,y+hh-22,14,22);
    ctx.fillStyle='#68847b';ctx.fillRect(x+12,y+27,13,11);ctx.fillRect(x+w-25,y+27,13,11);
    ctx.strokeStyle='#ead9ae';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+18,y+27);ctx.lineTo(x+18,y+38);ctx.moveTo(x+12,y+32);ctx.lineTo(x+25,y+32);ctx.stroke();
  }
  function drawResource(r,ox,oy){if(state.collected.has(r.id))return;const x=ox+(r.x+.5)*TILE,y=oy+(r.y+.5)*TILE;
    if(r.type==='berries'){ctx.fillStyle='#62734b';ctx.beginPath();ctx.arc(x,y+3,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c67565';ctx.beginPath();ctx.arc(x-3,y+1,2,0,6.3);ctx.arc(x+2,y-2,2,0,6.3);ctx.arc(x+3,y+4,2,0,6.3);ctx.fill();}
    else if(r.type==='fish'){ctx.fillStyle='#f0cb83';ctx.beginPath();ctx.ellipse(x,y,5,2.4,-.2,0,6.3);ctx.moveTo(x+4,y);ctx.lineTo(x+8,y-4);ctx.lineTo(x+8,y+4);ctx.fill();}
    else if(r.type==='bugs'){ctx.fillStyle='#e5cb77';ctx.beginPath();ctx.ellipse(x,y,3,2,0,0,6.3);ctx.fill();}
    else {ctx.fillStyle='#f5eee0';ctx.beginPath();ctx.ellipse(x,y,2,7,.55,0,6.3);ctx.fill();}
  }
  function drawCat(x,y,now){
    const bob=player.moving?Math.sin(now*.018)*1.6:Math.sin(now*.003)*.6;
    ctx.save();ctx.translate(x,y+bob);ctx.rotate(Math.atan2(player.dy,player.dx)+Math.PI/2);
    // soft little shadow
