node --input-type=module <<'NODE'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors=[]; page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://localhost:3002');
await page.click('#startButton');
const before = await page.locator('#coordText').textContent();
await page.keyboard.down('ArrowRight'); await page.waitForTimeout(800); await page.keyboard.up('ArrowRight');
const afterMove = await page.locator('#coordText').textContent();
await page.click('#mapButton'); const mapOpen = await page.locator('#mapOverlay').evaluate(e=>e.classList.contains('open'));
await page.keyboard.press('Escape'); const paused = await page.locator('#pauseBadge').evaluate(e=>e.classList.contains('show'));
await page.keyboard.press('Escape');
await page.keyboard.down('ArrowUp'); await page.waitForTimeout(9500); await page.keyboard.up('ArrowUp');
const location = await page.locator('#locationName').textContent();
await page.keyboard.press('Space'); await page.waitForTimeout(150);
console.log(JSON.stringify({before,afterMove,mapOpen,paused,location,thirst:await page.locator('#thirstValue').textContent(),errors}));
await browser.close();
NODE

